import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

.visible .entry max_reduce_kernel(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .s32 n0,
    .param .s32 n1,
    .param .s32 n2,
    .param .s32 axis,
    .param .s32 total_out
)
{
    .reg .s32 %r<40>;
    .reg .s64 %rd<20>;
    .reg .f32 %f<10>;
    .reg .pred %p<10>;

    ld.param.u64 %rd1, [in_ptr];
    ld.param.u64 %rd2, [out_ptr];
    ld.param.s32 %r1, [n0];
    ld.param.s32 %r2, [n1];
    ld.param.s32 %r3, [n2];
    ld.param.s32 %r4, [axis];
    ld.param.s32 %r5, [total_out];

    cvta.to.global.u64 %rd3, %rd1;
    cvta.to.global.u64 %rd4, %rd2;

    mov.u32 %r6, %ctaid.x;
    mov.u32 %r7, %ntid.x;
    mov.u32 %r8, %tid.x;
    mad.lo.s32 %r9, %r6, %r7, %r8;

    setp.ge.s32 %p1, %r9, %r5;
    @%p1 bra DONE;

    mul.lo.s32 %r10, %r2, %r3;   // s0 = n1*n2
    mov.s32 %r11, %r3;          // s1 = n2
    mov.s32 %r12, 1;            // s2 = 1

    setp.eq.s32 %p2, %r4, 0;
    @%p2 bra AXIS0;
    setp.eq.s32 %p3, %r4, 1;
    @%p3 bra AXIS1;
    bra AXIS2;

AXIS0:
    div.s32 %r13, %r9, %r3;
    rem.s32 %r14, %r9, %r3;
    mul.lo.s32 %r20, %r13, %r11;
    add.s32 %r15, %r20, %r14;
    mov.s32 %r16, %r10;
    mov.s32 %r17, %r1;
    bra REDUCE;

AXIS1:
    div.s32 %r13, %r9, %r3;
    rem.s32 %r14, %r9, %r3;
    mul.lo.s32 %r20, %r13, %r10;
    add.s32 %r15, %r20, %r14;
    mov.s32 %r16, %r11;
    mov.s32 %r17, %r2;
    bra REDUCE;

AXIS2:
    div.s32 %r13, %r9, %r2;
    rem.s32 %r14, %r9, %r2;
    mul.lo.s32 %r20, %r13, %r10;
    mul.lo.s32 %r21, %r14, %r11;
    add.s32 %r15, %r20, %r21;
    mov.s32 %r16, %r12;
    mov.s32 %r17, %r3;
    bra REDUCE;

REDUCE:
    mul.wide.s32 %rd6, %r15, 4;
    add.s64 %rd7, %rd3, %rd6;
    ld.global.f32 %f1, [%rd7];

    mov.s32 %r18, 1;
LOOP:
    setp.ge.s32 %p4, %r18, %r17;
    @%p4 bra STORE;
    mad.lo.s32 %r19, %r18, %r16, %r15;
    mul.wide.s32 %rd8, %r19, 4;
    add.s64 %rd9, %rd3, %rd8;
    ld.global.f32 %f2, [%rd9];
    max.f32 %f1, %f1, %f2;
    add.s32 %r18, %r18, 1;
    bra LOOP;

STORE:
    mul.wide.s32 %rd10, %r9, 4;
    add.s64 %rd11, %rd4, %rd10;
    st.global.f32 [%rd11], %f1;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("max_reduce_kernel")

class ModelNew(nn.Module):
    """
    Custom PTX-backed replacement for torch.max(x, dim=self.dim)[0]
    specialized for 3D float32 tensors.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.dim() == 3, "This kernel is specialized for 3D tensors."
        assert x.dtype == torch.float32, "This kernel is specialized for float32 tensors."
        x = x.contiguous()

        n0, n1, n2 = x.shape
        dim = self.dim
        if dim < 0:
            dim = dim + 3

        if dim == 0:
            out_shape = (n1, n2)
        elif dim == 1:
            out_shape = (n0, n2)
        elif dim == 2:
            out_shape = (n0, n1)
        else:
            raise ValueError("dim must be in [0, 2] for a 3D tensor")

        out = torch.empty(out_shape, dtype=x.dtype, device=x.device)

        total_out = out.numel()
        block_x = 256
        grid_x = (total_out + block_x - 1) // block_x

        module = _get_ptx_module()
        module.launch(
            "max_reduce_kernel",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[
                x,
                out,
                i32(n0),
                i32(n1),
                i32(n2),
                i32(dim),
                i32(total_out),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )

        return out

